{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance without encryption for root block device",
      "resource": "aws_instance.web",
      "severity": "HIGH",
      "explanation": "The root block device of the EC2 instance does not have encryption enabled. This can lead to sensitive data being exposed if the disk is compromised."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Added encryption to the root block device of the EC2 instance to ensure data at rest is protected."
}
